/* Progressive motion: native scrolling, no changes to account or data services. */
(()=>{
 const query=matchMedia('(prefers-reduced-motion:reduce)');const paused=()=>query.matches||document.body.classList.contains('motion-paused');
 const home=document.getElementById('mod-home');
 const story=document.createElement('section');story.className='orbit-story';story.setAttribute('aria-label','Un universo personale');
 story.innerHTML='<div class="orbit-sticky"><div class="orbit-story-art" aria-hidden="true"><img src="assets/art/chrome-loop.png" alt="" loading="lazy" width="1024" height="1024"><div class="orbit-track"></div></div><div class="orbit-story-copy"><span class="orbit-eyebrow">SPACE / INTORNO A TE</span><h2>Più spazio.<br><em>Più possibilità.</em></h2><p>Il tempo per organizzarti. La libertà di immaginare. La curiosità di andare oltre.</p><div class="orbit-chapters"><span class="is-current">01 — Organizza</span><span>02 — Immagina</span><span>03 — Esplora</span></div><button type="button" class="orbit-explore">Entra nel laboratorio <span aria-hidden="true">↗</span></button></div><span class="orbit-scroll-note">SCORRI. CAMBIA PROSPETTIVA.</span></div>';
 home.append(story);story.querySelector('button').onclick=()=>showModule('esperimenti',{transition:true});
 const headers=[...document.querySelectorAll('.module-heading')];headers.forEach((el,i)=>{el.classList.add('orbit-hero');el.style.setProperty('--chapter-hue',String(i*35));const art=document.createElement('div');art.className='orbit-hero-art';art.setAttribute('aria-hidden','true');art.innerHTML='<img src="assets/art/chrome-loop.png" alt="" loading="lazy" width="1024" height="1024">';el.append(art)});
 let frame=0;const chapters=[...story.querySelectorAll('.orbit-chapters span')];
 function paint(){frame=0;if(paused())return;const rect=story.getBoundingClientRect();if(rect.height&&rect.top<innerHeight&&rect.bottom>0){const progress=Math.max(0,Math.min(1,-rect.top/Math.max(1,rect.height-innerHeight)));story.style.setProperty('--story-progress',progress);chapters.forEach((el,i)=>el.classList.toggle('is-current',i===Math.min(2,Math.floor(progress*3))))}headers.forEach(el=>{if(!el.getClientRects().length)return;const r=el.getBoundingClientRect();el.style.setProperty('--hero-drift',Math.max(-50,Math.min(50,-r.top*.12))+'px')})}
 function requestPaint(){if(!frame&&!paused())frame=requestAnimationFrame(paint)}
 addEventListener('scroll',requestPaint,{passive:true});addEventListener('resize',requestPaint);addEventListener('workspace:module',requestPaint);
 const targets=[...document.querySelectorAll('.shortcut-card,.home-bottom-grid>*,.project-grid>.quick-card,.module-heading,.orbit-story-copy')];
 const running=new Set();let observer;
 if('IntersectionObserver' in window){observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;observer.unobserve(entry.target);if(paused()||!entry.target.animate)return;const animation=entry.target.animate([{opacity:.25,transform:'translateY(26px)'},{opacity:1,transform:'translateY(0)'}],{duration:850,easing:'cubic-bezier(.16,1,.3,1)'});running.add(animation);animation.finished.catch(()=>{}).finally(()=>running.delete(animation))}),{threshold:.12});targets.forEach(el=>observer.observe(el))}
 const cards=[...document.querySelectorAll('.project-grid>.quick-card,.inspiration-card')];
 if(matchMedia('(hover:hover) and (pointer:fine)').matches)cards.forEach(card=>{card.addEventListener('pointermove',e=>{if(paused())return;const r=card.getBoundingClientRect();card.style.setProperty('--light-x',(e.clientX-r.left)/r.width*100+'%');card.style.setProperty('--light-y',(e.clientY-r.top)/r.height*100+'%')},{passive:true});card.addEventListener('pointerleave',()=>{card.style.removeProperty('--light-x');card.style.removeProperty('--light-y')})});
 function syncMotion(){story.classList.toggle('orbit-static',paused());if(paused()){cancelAnimationFrame(frame);frame=0;running.forEach(a=>a.cancel());story.style.setProperty('--story-progress','0');headers.forEach(el=>el.style.setProperty('--hero-drift','0px'))}else requestPaint()}
 query.addEventListener('change',syncMotion);addEventListener('space:motion',syncMotion);syncMotion();
 addEventListener('pagehide',()=>{cancelAnimationFrame(frame);observer?.disconnect();running.forEach(a=>a.cancel())});
})();
